// Additional destinations and browser-local post-service checkout.
let extras={saved:['alex'],profile:{name:'John B.',email:'john@example.com'},blocks:[],reviews:[],invitations:[],campaigns:[],payment:'Choose at checkout',punches:3,seeded:false};
try{Object.assign(extras,JSON.parse(localStorage.getItem('hairflix-demo-v1')||'{}').extras||{});}catch{}
extras.catalog=services.map(s=>({...s}));
if(extras.staffVersion!=='lara-jose-1'){
 extras.barberProfile={};extras.saved=[...new Set((extras.saved||['alex']).map(id=>id==='chris'?'jordan':id))];
 for(const t of extras.conversations||[]){if(t.barber==='chris')t.barber='jordan';for(const m of t.messages||[]){if(m.role==='Barber Pro')m.name=m.name==='Alex Rivera'?'Lara':['Jordan Kim','Chris Brooks'].includes(m.name)?'Jose':m.name;}}
 for(const r of extras.reviews||[])if(r.barber==='chris')r.barber='jordan';
 for(const b of extras.blocks||[])if(b.barber==='chris')b.barber='jordan';
 extras.staffVersion='lara-jose-1';
}
if(extras.barberProfile)Object.assign(barbers[0],extras.barberProfile);
for(const b of barbers){if(extras.barberProfiles?.[b.id])Object.assign(b,extras.barberProfiles[b.id]);b.short=b.name.split(' ')[0];}
const screenIndex={
 Customer:[['home','Home'],['cWelcome','Welcome'],['cSignIn','Sign in'],['cSearch','Find a barber'],['cBarberProfile','Barber profile'],['cSaved','Saved barbers'],['cServices','Services menu'],['book','Booking: barber, service, time, review'],['success','Booking confirmation'],['bookings','My appointments'],['rewards','Punch card'],['cOffers','Offers'],['messages','Messages'],['cNotifications','Notifications'],['cProfile','My profile'],['cPayments','Payment preferences'],['cHelp','Help & support'],['cReview','Leave a review'],['cApproval','Approve final ticket & tip'],['cReceipt','Final receipt']],
 'Barber Pro':[['home','Today'],['pCalendar','Full calendar'],['pAppointment','Appointment detail'],['clients','Client directory'],['pClient','Client detail & history'],['availability','Weekly availability'],['pBlock','Block time / time off'],['pServices','Service menu editor'],['earnings','Earnings'],['pPayout','Payout detail'],['pProfile','Public profile editor'],['pNotifications','Notifications'],['pTickets','Live tickets'],['pTicket','Live ticket editor'],['pFinalize','Finalize & send ticket']],
 'Owner HQ':[['home','Shop overview'],['calendar','Master calendar'],['team','Team directory'],['hMember','Team-member detail'],['hInvite','Invite a team member'],['hCustomers','Customer directory'],['hCustomer','Customer detail'],['hServices','Shop services editor'],['reports','Revenue reports'],['hPerformance','Barber performance'],['hPayouts','Transactions & payouts'],['hNotifications','Notifications'],['hLoyalty','Loyalty management'],['hMarketing','Marketing & promotions'],['hMessages','Shop messages'],['settings','Shop settings']]
};
Object.assign(state,{services:['cut'],visitId:null,clientIndex:0,member:'alex',postTip:null,tipCustom:'',approvalRevision:null,search:'',filter:'All',reviewStars:5,pageError:'',noteDraft:''});
for(const b of bookings){b.client=b.client||'John B.';b.estimateCents=b.estimateCents??Math.round(services.find(s=>s.id===b.service).price*100);if(!b.bookedServices){b.bookedServices=[{...services.find(s=>s.id===b.service),price:b.estimateCents/100}];b.services=b.bookedServices.map(s=>s.id);}b.location=b.location||'scottsdale';if(!b.ticket?.approval){b.tip=0;b.total=b.estimateCents/100;}}
function seedVisit(){let b=bookings.find(x=>x.id.startsWith('demo-live')&&(x.location||'scottsdale')===(extras.location||'scottsdale')&&x.status!=='cancelled'&&x.ticket?.status!=='approved');if(!b){const svc=services.find(s=>s.id==='cut')||services[0];b={id:bookings.some(x=>x.id==='demo-live')?'demo-live-'+Date.now():'demo-live',client:'John B.',barber:'alex',service:svc.id,location:extras.location||'scottsdale',date:today,time:'9:00 AM',status:'in_service',estimateCents:Math.round(svc.price*100),total:svc.price,tip:0};b.ticket=HFTickets.create(b.id,svc);bookings.push(b);checked[b.id]=true;}state.visitId=b.id;return b;}
if(!extras.seeded){seedVisit();extras.seeded=true;save();}
const xbutton=(label,action,cls='',attrs='')=>`<button type="button" class="btn ${cls}" data-x="${action}" ${attrs}>${label}</button>`;
const linkPage=(label,page,role=state.role,cls='secondary small',attrs='')=>xbutton(label,'goto',cls,`data-page="${page}" data-r="${role}" ${attrs}`);
const cents=n=>money(n/100);
const roleHome=()=>linkPage(`${icon('back')} Back to ${state.role==='Customer'?'home':state.role==='Barber Pro'?'today':'overview'}`,'home',state.role,'secondary small');
const errorBox=()=>state.pageError?`<p class="form-error" role="alert">${esc(state.pageError)}</p>`:'';
function visitFor(id=state.visitId){const allowed=b=>state.role==='Customer'?b.client==='John B.':state.role==='Barber Pro'?b.barber===activeBarberId():true;return bookings.find(b=>b.id===id&&allowed(b))||bookings.find(b=>b.ticket&&b.status!=='cancelled'&&allowed(b))||bookings.find(b=>b.status!=='cancelled'&&allowed(b));}
function ticketFor(b){if(!b)return null;if(!b.ticket){b.ticket=HFTickets.create(b.id,b.bookedServices||services.find(s=>s.id===b.service));save();}return b.ticket;}
function freshVisit(id){try{const incoming=JSON.parse(localStorage.getItem('hairflix-demo-v1')||'{}').bookings?.find(b=>b.id===id);if(incoming){const i=bookings.findIndex(b=>b.id===id);if(i>=0)bookings[i]=incoming;}}catch{}return bookings.find(b=>b.id===id);}
function statusLabel(t){return {draft:'Open ticket',finalized:'Finalized · not sent',awaiting_approval:'Waiting for client',changes_requested:'Changes requested',approved:'Client approved'}[t?.status]||'Upcoming';}
function customerNameBadges(name){const vip=name==='Alex Morgan',isNew=clientRecords.find(c=>c.name===name)?.visits===0;return `<span class="client-name-text">${esc(name)}</span>${isNew?'<span class="new-customer-badge">New customer</span>':vip?'<span class="vip-customer-badge" title="VIP · generous tipper">VIP</span>':''}`;}
function upcomingVisitBadge(b,now=Date.now()){const upcoming=b&&!checked[b.id]&&!b.ticket?.approval&&['confirmed','pending_payment'].includes(b.status)&&(!b.ticket||b.ticket.status==='draft');if(!upcoming)return ticketBadge(b?.ticket);const remaining=Math.ceil((HFAppRules.appointmentAt(b)-now)/60000);return `<span class="badge upcoming-badge" data-upcoming-id="${esc(b.id)}">${remaining>0&&remaining<=30?'Soon · '+remaining+' min'+(remaining===1?'':'s'):'Upcoming'}</span>`;}
function refreshUpcomingBadges(){document.querySelectorAll('[data-upcoming-id]').forEach(el=>{const b=bookings.find(b=>b.id===el.dataset.upcomingId);if(!b)return;const remaining=Math.ceil((HFAppRules.appointmentAt(b)-Date.now())/60000);el.textContent=remaining>0&&remaining<=30?'Soon · '+remaining+' min'+(remaining===1?'':'s'):'Upcoming';el.classList.toggle('visit-soon',remaining>0&&remaining<=30);});}
setInterval(refreshUpcomingBadges,30000);
function ticketBadge(t){const waiting=t?.status==='awaiting_approval';return `<span class="badge ${t?.status==='changes_requested'?'cancelled':''} ${waiting?'ticket-waiting':''}" ${waiting?'role="status"':''}>${waiting?'<span class="ticket-spinner" aria-hidden="true"></span>':''}${statusLabel(t)}</span>`;}
function openTicketFor(id){let b=bookings.find(b=>b.id===id);if(b&&state.role==='Barber Pro'&&b.barber!==activeBarberId())throw new Error('This appointment belongs to another barber.');if(!b&&id.startsWith('sample')){const idx=Number(id.match(/^sample(\d)/)?.[1]||0),slot=sampleSlots[idx],service=idx===1?'combo':idx===2?'beard':'cut';b={id,client:slot[1],barber:'alex',service,location:extras.location||'scottsdale',date:state.calendarDate,time:slot[0],status:'in_service',estimateCents:Math.round(services.find(s=>s.id===service).price*100),tip:0,total:services.find(s=>s.id===service).price};bookings.push(b);}if(!b)return;checked[b.id]=true;if(b.status==='confirmed')b.status='in_service';state.visitId=b.id;ticketFor(b);save();go('pAppointment');}
function visitSummary(b){const t=b.ticket;return `<div class="ticket-meta"><div class="row">${appointmentPortrait(b)}<div><h3 class="client-name-row">${customerNameBadges(b.client)}</h3><p class="muted">${barbers.find(x=>x.id===b.barber).name} · ${pretty(b.date)} · ${b.time}</p></div></div>${upcomingVisitBadge(b)}</div>`;}
function lineSummary(lines){return `<div class="ticket-lines">${lines.map(l=>`<div class="line-item"><div><strong>${esc(l.name)}</strong><br><small>${cents(l.cents)}</small></div><strong>${cents(l.qty*l.cents)}</strong></div>`).join('')}</div>`;}
function missingVisit(title){return `${head(title,'Choose an appointment or load the sample live visit.')}<div class="empty">${icon('scissors')}<h2>No visit selected.</h2>${xbutton('Try sample live ticket','try-ticket')}${linkPage('My appointments','bookings','Customer','secondary','style="margin-left:10px"')}</div>`;}
function renderExtraView(v){if(v==='more'||v==='map')return directory(v==='map');const renderers={cWelcome:welcomePage,cSignIn:signInPage,cSearch:searchPage,cBarberProfile:barberProfile,cSaved:savedPage,cServices:()=>serviceMenu(false),cOffers:offersPage,cNotifications:notificationsPage,cProfile:customerProfile,cPayments:paymentsPage,cHelp:helpPage,cReview:reviewPage,cApproval:approvalPage,cReceipt:receiptPage,pCalendar:()=>proCalendar(false),pAppointment:appointmentDetail,pClient:()=>clientDetail(false),pBlock:blockPage,pServices:()=>serviceMenu(true),pPayout:()=>payoutPage(false),pProfile:proProfile,pNotifications:notificationsPage,pTickets:ticketList,pTicket:ticketEditor,pFinalize:finalizePage,hMember:memberPage,hInvite:invitePage,hCustomers:()=>clientDirectory(true),hCustomer:()=>clientDetail(true),hServices:()=>serviceMenu(true),hPerformance:performancePage,hPayouts:()=>payoutPage(true),hNotifications:notificationsPage,hLoyalty:loyaltyPage,hMarketing:marketingPage,hMessages:shopMessages};return renderers[v]?renderers[v]():null;}
function directory(all=false){return `${head(all?'Every page, one place.':'More from HAIRFLIX.',all?'54 screens across three roles, including four booking steps.':'Choose where you’d like to go next.')}<div class="page-directory">${(all?Object.keys(screenIndex):[state.role]).map(role=>`<section><h2>${role}</h2><div class="directory-links">${screenIndex[role].map(([page,label])=>`<button data-x="goto" data-page="${page}" data-r="${role}"><span>${label}</span>${icon('chevron')}</button>`).join('')}</div></section>`).join('')}</div>`;}
function ticketList(){const live=bookings.filter(b=>b.status!=='cancelled'&&(state.role==='Owner HQ'||b.barber===activeBarberId()));return `${head('From first snip to final approval.','Services can change. The client always approves the final version.',xbutton('Try sample live ticket','try-ticket','small'))}<div class="workflow-steps"><span>1. Open ticket</span><span>2. Edit services</span><span>3. Finalize & send</span><span>4. Client approves & tips</span></div>${live.length?live.map(b=>`<button class="ticket-link" data-x="open-visit" data-id="${b.id}">${appointmentPortrait(b)}<div class="details"><strong>${esc(b.client)}</strong><p>${pretty(b.date)} · ${b.time} · ${bookingName(b)}</p></div><div>${ticketBadge(b.ticket)}${icon('chevron')}</div></button>`).join(''):`<div class="empty"><h2>No open visits.</h2><p>Bookings and started visits will appear here.</p></div>`}`;}
function appointmentDetail(){const b=visitFor();if(!b)return missingVisit('Appointment detail.');const t=b.ticket;return `${head('Appointment details.','',linkPage('All tickets','pTickets'))}${visitSummary(b)}<div class="review-grid"><section class="panel"><h2>Booked service</h2><div class="line-item"><span>${bookingName(b)}</span><strong>${cents(b.estimateCents)}</strong></div><div class="line-item"><span>Duration booked</span><strong>${bookingDuration(b)} min</strong></div><p class="chart-note">The booked estimate stays on record even if the live services change.</p><div class="section-head"><h3>Client preferences</h3></div><p class="muted">Low taper. Keep length on top. Prefers a relaxed appointment.</p></section><section class="panel"><h2>Live ticket</h2><div class="line-item"><span>Current service subtotal</span><strong>${cents(t?HFTickets.subtotal(t):b.estimateCents)}</strong></div><p class="chart-note">No pre-tip. Tipping happens after services are finalized and sent to the client.</p>${!checked[b.id]&&b.status==='confirmed'?xbutton('Check in & start live ticket','start-ticket','full',`data-id="${b.id}" style="margin-top:20px"`):linkPage(t?.status==='approved'?'View approved ticket':'Open live ticket','pTicket',state.role,'full','style="margin-top:20px"')}</section></div>`;}
function ticketEditor(){const b=visitFor();if(!b)return missingVisit('Live ticket.');if(b.status==='confirmed'&&!checked[b.id])return appointmentDetail();const t=ticketFor(b),editable=['draft','changes_requested'].includes(t.status);state.visitId=b.id;return `${head('The work, as it happened.','Live ticket · Revision '+t.revision,linkPage('Appointment detail','pAppointment',state.role))}${visitSummary(b)}${errorBox()}${t.note?`<div class="notice"><strong>Client’s change request</strong><p>${esc(t.note)}</p></div>`:''}<div class="ticket-layout"><section><h2>Services on this visit</h2>${editable?`<div id="ticket-line-editor" data-revision="${t.revision}">${t.lines.map(l=>`<form class="ticket-line-form" data-line="${l.id}"><label>Service name<input name="name" aria-label="Service name" value="${esc(l.name)}" maxlength="80" required></label><label>Price ($)<input name="price" aria-label="Service price" type="number" min="0" max="1000" step="0.01" value="${(l.cents/100).toFixed(2)}" required></label><input name="qty" type="hidden" value="1"><button type="button" class="icon-btn" data-x="remove-line" data-line="${l.id}" aria-label="Remove ${esc(l.name)}">${icon('close')}</button></form>`).join('')}</div>${!t.lines.length?'<div class="notice">No services left. Add a service before finalizing, or cancel an unstarted visit.</div>':''}<div class="flex-buttons" style="margin:18px 0">${xbutton('Save line changes','save-lines','secondary')}</div><section class="add-service"><h3>Add a service</h3><form id="add-ticket-service"><label>Service<select name="service" id="ticket-service-select">${services.filter(s=>s.active!==false).map(s=>`<option value="${s.id}">${esc(s.name)} · ${money(s.price)}</option>`).join('')}<option value="custom">Custom service</option></select></label><label>Custom name (if needed)<input name="customName" maxlength="80" placeholder="e.g. Hot towel treatment"></label><label>Price for this visit ($)<input name="price" id="ticket-add-price" type="number" min="0" max="1000" step="0.01" value="${services.find(s=>s.active!==false).price.toFixed(2)}" required></label><button class="btn secondary" type="submit">${icon('scissors')} Add to ticket</button></form></section>`:lineSummary(t.snapshot?.lines||t.lines)}</section><aside class="panel ticket-totals"><h2>Ticket summary</h2><div class="line-item"><span>Booked estimate</span><strong>${cents(b.estimateCents)}</strong></div><div class="line-item"><span>Current service subtotal</span><strong>${cents(HFTickets.subtotal(t))}</strong></div><div class="line-item"><span>Tip</span><small>${t.approval?cents(t.approval.tipCents):'Chosen by client after cut'}</small></div>${t.approval?`<div class="line-item total"><strong>Approved total</strong><strong>${cents(t.approval.totalCents)}</strong></div>`:''}${editable?xbutton('Review & finalize','review-ticket','full','style="margin-top:20px"'):t.status==='finalized'?linkPage('Review & send','pFinalize',state.role,'full','style="margin-top:20px"'):t.status==='awaiting_approval'?xbutton('Preview client approval','preview-client','full','style="margin-top:20px"'):''}${['finalized','awaiting_approval'].includes(t.status)?xbutton('Reopen to make changes','reopen-ticket','secondary full','style="margin-top:12px"'):''}<div class="section-head"><h3>Ticket history</h3></div><ol class="ticket-history">${t.history.slice(-5).map(h=>`<li>${esc(h.event)} <small>· v${h.revision}</small></li>`).join('')}</ol></aside></div>`;}
function finalizePage(){const b=visitFor();if(!b)return missingVisit('Finalize ticket.');if(b.status==='confirmed'&&!checked[b.id])return appointmentDetail();const t=ticketFor(b);if(!['finalized','draft','changes_requested'].includes(t.status))return ticketEditor();return `${head('One final check.','Confirm the actual services before asking your client to approve.',linkPage('Back to ticket','pTicket',state.role))}${visitSummary(b)}${errorBox()}<div class="review-grid"><section class="panel"><h2>Final services</h2>${lineSummary(t.lines)}<div class="line-item total"><strong>Service subtotal</strong><strong>${cents(HFTickets.subtotal(t))}</strong></div></section><section class="panel"><h2>Send after the cut is finished.</h2><p class="muted" style="margin-top:14px">The client will see every final service and price, the booked estimate, and the difference. They can request a correction or approve and add an optional tip.</p>${t.status==='finalized'?xbutton(`${icon('send')} Send to client for approval`,'send-ticket','full','style="margin-top:22px"'):xbutton('Finalize this ticket','finalize-ticket','full','style="margin-top:22px"')}</section></div>`;}
function approvalPage(){const pending=bookings.filter(b=>b.client==='John B.'&&b.ticket?.status==='awaiting_approval');const b=pending.find(b=>b.id===state.visitId)||pending[0];if(!b)return `${head('Your final ticket.','Your barber sends this after the cut is finished.')}<div class="empty">${icon('wallet')}<h2>Nothing waiting for approval.</h2><p>${bookings.some(b=>b.client==='John B.'&&b.ticket?.status==='changes_requested')?'Your barber is reviewing your correction request. They’ll resend the revised ticket.':'When your barber finalizes and sends a ticket, you’ll review the services and choose a tip here.'}</p>${linkPage('My appointments','bookings','Customer')}${xbutton('Try sample live ticket','try-ticket','secondary','style="margin-left:10px"')}</div>`;state.visitId=b.id;const t=b.ticket,snap=t.snapshot;const tipKey=b.id+':'+t.revision;if(state.tipKey!==tipKey){state.tipKey=tipKey;state.postTip=null;state.tipCustom='';}state.approvalRevision=t.revision;let tip=postTipCents(snap.subtotalCents),total=snap.subtotalCents+(tip??0);return `${head('How was your visit?','Review the final services. Then choose your tip.',linkPage('My visits','bookings','Customer'))}${visitSummary(b)}${pending.length>1?`<div class="ticket-picker">${pending.map(x=>xbutton(`${pretty(x.date)} · ${x.time}`,'select-approval','secondary small',`data-id="${x.id}"`)).join('')}</div>`:''}${errorBox()}<div class="review-grid"><section class="panel"><h2>What you received</h2>${lineSummary(snap.lines)}<details class="ticket-original"><summary>Compare with originally booked services</summary>${lineSummary(t.original)}</details><div class="line-item"><span>Booked service estimate</span><strong>${cents(b.estimateCents)}</strong></div><div class="line-item"><span>Final services</span><strong>${cents(snap.subtotalCents)}</strong></div><div class="change-summary">${snap.subtotalCents===b.estimateCents?'Total unchanged from your booked estimate.':`${snap.subtotalCents>b.estimateCents?'Added':'Removed'} ${cents(Math.abs(snap.subtotalCents-b.estimateCents))} compared with the booked estimate.`}</div><p class="chart-note">Revision ${t.revision} · Sent ${new Date(t.sentAt).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})}</p></section><section class="panel"><h2>A thank-you, your way.</h2><p class="muted" style="font-size:13px;margin-top:12px">Optional. Tip on the final service subtotal, after your visit.</p><div class="tip-options post-tips" role="group" aria-label="Post-service tip">${['none',15,18,20,'custom'].map(p=>`<button data-x="post-tip" data-value="${p}" class="${String(state.postTip)===String(p)?'selected':''}" aria-pressed="${String(state.postTip)===String(p)}">${p==='none'?'No tip':p==='custom'?'Custom':p+'%'}</button>`).join('')}</div>${state.postTip==='custom'?`<form id="custom-tip-form"><label for="custom-tip">Tip amount ($)</label><div class="row"><input id="custom-tip" name="tip" type="number" min="0" max="1000" step="0.01" value="${esc(state.tipCustom)}" required><button class="btn secondary small" type="submit">Apply tip</button></div></form>`:''}<div class="line-item"><span>Final services</span><strong>${cents(snap.subtotalCents)}</strong></div><div class="line-item"><span>Your tip</span><strong>${tip===null?'Choose above':cents(tip)}</strong></div><div class="line-item total"><strong>Total to approve</strong><strong>${cents(total)}</strong></div><label class="approval-consent"><input id="approve-services" type="checkbox"> I’ve reviewed these final services and prices.</label>${xbutton('Approve final ticket'+(tip!==null?' · '+cents(total):''),'approve-ticket','full',`data-revision="${snap.revision}" ${tip===null?'disabled':''}`)}</section></div>`;}
function postTipCents(base){if(state.postTip===null)return null;if(state.postTip==='none')return 0;if(state.postTip==='custom'){const n=Number(state.tipCustom);return state.tipCustom!==''&&Number.isFinite(n)&&n>=0&&n<=1000?Math.round(n*100):null;}return Math.round(base*Number(state.postTip)/100);}
function receiptPage(){const b=bookings.find(b=>b.id===state.visitId&&b.client==='John B.'&&b.ticket?.approval)||[...bookings].reverse().find(b=>b.client==='John B.'&&b.ticket?.approval);if(!b)return `${head('Your visit receipt.','Receipts appear after you approve the final ticket.')}<div class="empty"><h2>No approved tickets yet.</h2>${linkPage('View final ticket','cApproval','Customer')}</div>`;const a=b.ticket.approval;return `<div class="receipt"><div class="success-mark">${icon('check')}</div>${head('All taken care of.','Thanks for trusting '+barbers.find(x=>x.id===b.barber).short+' with your look.')}<div class="panel">${visitSummary(b)}${lineSummary(a.lines)}<div class="line-item"><span>Final services</span><strong>${cents(a.subtotalCents)}</strong></div><div class="line-item"><span>Tip</span><strong>${cents(a.tipCents)}</strong></div><div class="line-item total"><strong>Approved total</strong><strong>${cents(a.totalCents)}</strong></div></div><div class="flex-buttons" style="margin-top:20px">${linkPage('Send private feedback','cReview','Customer','')}${linkPage('My punch card','rewards','Customer')}</div></div>`;}
function textField(label,name,value='',type='text',attrs=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;}
function welcomePage(){return `<section class="welcome-hero"><img src="assets/shop.jpg" alt="Barber finishing a precise beard trim"><div>${logo()}<h1>Look good.<br>Feel like yourself.</h1><p>Your barber, your time, your next great cut.</p><div class="flex-buttons">${linkPage('Get started','cSignIn','Customer','')}${linkPage('Explore the shop','home','Customer')}</div></div></section>`;}
function signInPage(){return `<div class="narrow">${head('Your chair is waiting.','Sign in for the HAIRFLIX app.')}<form id="demo-signin" class="panel"><h2>Welcome back</h2>${textField('Your display name','name',extras.profile.name,'text','required maxlength="80"')}<label class="field">Switch role<select name="role"><option>Customer</option><option>Barber Pro</option><option>Owner HQ</option></select></label><button class="btn full" type="submit">Continue</button><p class="chart-note">No password, account creation or real authentication. The role switch remains available for testing.</p></form></div>`;}
function searchPage(){const matches=barbers.filter(b=>(state.filter==='All'||b.specialty.toLowerCase().includes(state.filter.toLowerCase()))&&(b.name+' '+b.specialty).toLowerCase().includes(state.search.toLowerCase()));return `${head('Find your kind of barber.','A good connection makes a great cut.')}<form id="barber-search" class="search-form"><input name="query" aria-label="Search barbers" placeholder="Name or specialty" value="${esc(state.search)}"><button class="btn secondary" type="submit">Search</button></form><div class="filter-row">${['All','Fades','Beards','Texture'].map(f=>xbutton(f,'filter','secondary small '+(f===state.filter?'selected':''),`data-value="${f}"`)).join('')}</div><div class="profile-results">${matches.length?matches.map(b=>`<button class="profile-result" data-x="barber-profile" data-id="${b.id}">${photo(b,'avatar square')}<div><h2>${b.name}</h2><p>${b.specialty}</p></div>${icon('chevron')}</button>`).join(''):'<div class="empty"><h2>No matches yet.</h2><p>Try another name or choose All specialties.</p></div>'}</div>`;}
function barberProfile(){const b=B();return `${head('Meet '+b.short+'.',b.specialty,linkPage('All barbers','cSearch','Customer'))}<div class="profile-cover">${photo(b,'profile-portrait')}<div><h1>${esc(b.name)}</h1><p>${esc(b.bio||('Precision, a little patience, and a cut that feels like you. '+b.short+' takes time to understand your hair, your routine, and what you want to walk out with.'))}</p><div class="flex-buttons">${xbutton(icon('calendar')+' Book '+b.short,'book-barber','')}${xbutton(icon('message')+' Message','message-barber','secondary')}${xbutton(icon('star')+(extras.saved.includes(b.id)?' Favorite':' Make favorite'),'save-barber','secondary')}</div></div></div><section><h2>Services</h2>${servicesFor(state.barber).filter(s=>s.active!==false).map(s=>`<div class="list-item">${icon('scissors')}<div class="details"><strong>${esc(s.name)}</strong><p>${s.min} min</p></div><strong>${money(s.price)}</strong></div>`).join('')}</section>`;}
function savedPage(){return `${head('Your people, saved.','A familiar face is only a tap away.',linkPage('Find more barbers','cSearch','Customer'))}<div class="profile-results">${barbers.filter(b=>extras.saved.includes(b.id)).map(b=>`<button class="profile-result" data-x="barber-profile" data-id="${b.id}">${photo(b,'avatar square')}<div><h2>${b.name}</h2><p>${b.specialty}</p></div>${icon('chevron')}</button>`).join('')||'<div class="empty"><h2>Your next favorite is out there.</h2><p>Save a barber from their profile to keep them here.</p></div>'}</div>`;}
function serviceMenu(editable){const list=services;return `${head(editable?'A menu that reflects your craft.':'A service for your next chapter.',editable?'Edit the menu. Existing live tickets keep their own prices.':'Booked prices are estimates; approve your final ticket after the visit.',editable?xbutton('Add a service','new-service','small'):linkPage('Book a visit','book','Customer',''))}${errorBox()}<div class="service-menu">${list.filter(s=>editable||s.active!==false).map(s=>`<div class="service-row">${icon('scissors')}<div><h3>${esc(s.name)}</h3><p>${esc(s.desc)} · ${s.min} min</p></div><strong>${money(s.price)}</strong>${editable?`<div class="flex-buttons">${xbutton('Edit','edit-service','secondary small',`data-id="${s.id}"`)}${xbutton(s.active===false?'Enable':'Hide','toggle-service','secondary small',`data-id="${s.id}"`)}</div>`:linkPage('Choose','book','Customer','secondary small')}</div>`).join('')}</div>${editable?`<section id="service-editor-panel" class="panel narrow" ${state.editService?'':'hidden'} style="margin:25px 0"><h2>${state.editService==='new'?'Add a service':'Edit service'}</h2><form id="catalog-service-form" data-id="${state.editService||'new'}">${textField('Service name','name',services.find(s=>s.id===state.editService)?.name||'','text','required maxlength="80"')}${textField('Description','desc',services.find(s=>s.id===state.editService)?.desc||'','text','required maxlength="180"')}${textField('Price ($)','price',services.find(s=>s.id===state.editService)?.price??30,'number','required min="0" max="1000" step="0.01"')}${textField('Duration (minutes)','min',services.find(s=>s.id===state.editService)?.min??30,'number','required min="5" max="240" step="5"')}<button class="btn" type="submit">Save service</button></form></section>`:''}`;}
function offersPage(){return `${head('A little extra, just for you.','Offers and membership benefits at the shop.')}<div class="offer-feature"><div>${icon('gift')}<h1>Your next reward<br>is a good look.</h1><p>Complete ${extras.loyalty?.threshold||5} eligible visits to unlock $${extras.loyalty?.reward||10} off a service.</p>${linkPage('View my punch card','rewards','Customer','')}</div></div><div class="list"><div class="list-item">${icon('crown')}<div class="details"><strong>Birthday special</strong></div>${xbutton('View details','offer-details','secondary small')}</div><div class="list-item">${icon('users')}<div class="details"><strong>Bring a friend</strong></div>${linkPage('Message the shop','messages','Customer')}</div></div><div id="offer-details"></div>`;}
function customerProfile(){return `<div class="narrow">${head('Make yourself at home.','Your details and preferences.')}<form id="customer-profile-form" class="panel">${textField('Display name','name',extras.profile.name,'text','required maxlength="80"')}${textField('Email address','email',extras.profile.email,'email','required')}${textField('Phone number','phone',extras.profile.phone||'','tel','autocomplete="tel" maxlength="30"')}${textField('Hair preferences','preferences',extras.profile.preferences||'Low taper, keep length on top.','text','maxlength="250"')}<label class="check-row"><input name="reminders" type="checkbox" ${extras.profile.reminders!==false?'checked':''}> Appointment reminder preference</label><button class="btn" type="submit">Save profile on this browser</button></form></div>`;}
function paymentsPage(){return `<div class="narrow">${head('Pay your way, after the cut.','Payment preference preview.')}<section class="panel"><h2>No payment taken at booking.</h2><p class="muted" style="margin:14px 0">Your barber sends the final ticket when the services are complete. You approve the actual services and select an optional tip then.</p><div class="booking-choices">${['Choose at checkout','Pay at shop','Digital wallet'].map(p=>`<button class="choice ${extras.payment===p?'selected':''}" data-x="payment-pref" data-value="${p}"><div class="details"><strong>${p}</strong></div><span class="check">${extras.payment===p?icon('check'):''}</span></button>`).join('')}</div></section></div>`;}
function helpPage(){return `<div class="narrow">${head('We’ve got you.','A little help before your next visit.')}<div class="faq">${[['Can my total change after I book?','Yes. The barber can adjust the services on the live ticket. You see the final itemized services and prices before approving them.'],['When do I tip?','After the barber finishes, finalizes the ticket and sends it to you. A tip is optional; no tip is selected automatically.'],['What if a service or price is wrong?','Request a correction from the final-ticket screen. Your barber revises the ticket and sends a new version for approval.'],['Can I reschedule?','Use My visits before your appointment starts. Once a live ticket is in progress, speak to the barber instead.'],['Can I message my barber?','Yes. Open Messages or use the message button on their profile. ']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></div>`;}
function reviewPage(){const eligible=bookings.filter(b=>b.client==='John B.'&&b.ticket?.status==='approved');return `<div class="narrow">${head('How did we do?','Leave feedback after an approved, completed visit.')}${eligible.length?`<form id="client-review" class="panel"><label class="field">Completed visit<select name="visit">${eligible.map(b=>`<option value="${b.id}">${pretty(b.date)} · ${barbers.find(x=>x.id===b.barber).name}</option>`).join('')}</select></label><label class="field">Your rating<select name="stars"><option value="5">5 — Excellent</option><option value="4">4 — Great</option><option value="3">3 — Good</option><option value="2">2 — Could improve</option><option value="1">1 — Disappointing</option></select></label><label class="field">Your review<textarea name="review" rows="4" maxlength="1000" minlength="3" required placeholder="What stood out about your visit?"></textarea></label><button class="btn" type="submit">Save review</button></form>`:`<div class="empty">${icon('star')}<h2>A review follows a real experience.</h2>${linkPage('View final ticket','cApproval','Customer')}</div>`}${extras.reviews.length?`<div class="section-head"><h2>Your saved reviews</h2></div>${extras.reviews.map(r=>`<div class="panel" style="margin-top:14px"><strong>${r.stars} / 5</strong><p>${esc(r.review)}</p></div>`).join('')}`:''}</div>`;}
function myBookings(){const list=[...bookings].filter(b=>b.client==='John B.').sort((a,b)=>b.date.localeCompare(a.date)||minutes(b.time)-minutes(a.time));return `${head('Your time in the chair.','From your first booking to your final receipt.',button('Book a cut','start','small'))}${list.length?list.map(b=>{const t=b.ticket,active=!t||t.status==='draft',canChange=b.status==='confirmed'&&!checked[b.id];return `<section class="appointment-card"><div class="row between"><span class="date-label">${pretty(b.date)} · ${b.time}</span>${b.status==='cancelled'?'<span class="badge cancelled">Cancelled</span>':ticketBadge(t)}</div><div class="row" style="margin-top:15px">${photo(barbers.find(x=>x.id===b.barber))}<div><h3>${bookingName(b)}</h3><p>${barbers.find(x=>x.id===b.barber).name} · Booked estimate ${cents(b.estimateCents)}</p></div></div><div class="appointment-actions">${t?.status==='awaiting_approval'?xbutton('Review final ticket & tip','select-approval','',`data-id="${b.id}"`):t?.status==='approved'?xbutton('View final receipt','receipt','secondary',`data-id="${b.id}"`):b.status!=='cancelled'?`<small>${t?'Your barber is working on the final ticket. No tip yet.':'No payment or tip taken at booking.'}</small>`:''}${canChange?`${button('Reschedule','reschedule','secondary small',`data-id="${b.id}"`)}${button('Cancel visit','cancel','secondary small',`data-id="${b.id}"`)}`:''}</div>${state.cancelId===b.id?`<div class="confirmation">Cancel this appointment?<div class="flex-buttons">${button('Keep appointment','keep','secondary small')}${button('Yes, cancel visit','cancel-confirm','danger small',`data-id="${b.id}"`)}</div></div>`:''}</section>`}).join(''):`<div class="empty"><h2>Find your next great cut.</h2><p>Your upcoming and completed visits will appear here.</p>${button('Book a visit','start')}</div>`}`;}
const clientRecords=[{name:'John B.',visits:8,note:'Low taper. Keep length on top.',img:'demo-cut-lara.png'},{name:'Alex Morgan',visits:5,note:'Scissor cut, natural finish.',img:'demo-cut-watkins.png'},{name:'Ryan Smith',visits:3,note:'Beard sculpt. Prefers morning appointments.',img:'demo-cut-jose.png'}];
function clientPhoto(name,cls='avatar customer-portrait'){
 const client=clientRecords.find(c=>c.name===name);
 if(client?.img)return photo(client,cls);
 const initials=String(name||'Client').trim().split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase();
 return `<span class="account-initials customer-portrait ${esc(cls)}" role="img" aria-label="${esc(name||'Client')}">${esc(initials)}</span>`;
}
function matchedPortraits(client,barber){
 const staff=barbers.find(b=>b.id===barber);
 if(!staff)return clientPhoto(client);
 return `<span class="matched-portraits" role="group" aria-label="${esc(client)} with ${esc(staff.name)}">${clientPhoto(client)}${photo(staff,'avatar matched-barber')}</span>`;
}
function appointmentPortrait(b){
 if(state.role==='Owner HQ')return matchedPortraits(b.client,b.barber);
 if(state.role==='Barber Pro')return clientPhoto(b.client);
 return photo(barbers.find(x=>x.id===b.barber));
}

function clientDirectory(owner){return `${head(owner?'Know the people behind the bookings.':'Your regulars, remembered.',owner?'Customer directory · All shop clients':'Client directory · Your chair, your relationships')}<div class="profile-results">${clientRecords.map((c,i)=>`<button class="profile-result" data-x="client-detail" data-index="${i}" data-owner="${owner}">${photo(c,'avatar square')}<div><h2>${c.name}</h2><small>${esc(c.note)}</small></div>${icon('chevron')}</button>`).join('')}</div>`;}
function clients(){return clientDirectory(false);}
function clientDetail(owner){const c=clientRecords[state.clientIndex]||clientRecords[0];return `${head(c.name,'Client detail & visit history',linkPage('Back to clients',owner?'hCustomers':'clients',state.role))}<div class="review-grid"><section class="panel"><div class="row">${photo(c,'avatar square')}<div><h2>${c.name}</h2><p class="muted">${c.visits} visits · Member since March</p></div></div><div class="section-head"><h3>Preferences worth remembering</h3></div><form id="client-note-form"><label class="field">Private client note<textarea name="note" rows="4" maxlength="500">${esc(extras.clientNotes?.[c.name]||c.note)}</textarea></label><button class="btn secondary" type="submit">Save note</button></form></section><section><h2>Visit history</h2>${xbutton('Message client','message-client','secondary','style="margin-top:15px"')}${[['Sep 29','Signature haircut','$30'],['Aug 28','Haircut + beard','$40'],['Jul 30','Signature haircut','$30']].map(([date,n,total])=>`<div class="list-item">${icon('calendar')}<div class="details"><strong>${n}</strong></div><strong>${total}</strong></div>`).join('')}${c.name==='John B.'?bookings.filter(b=>b.ticket?.approval).map(b=>`<div class="list-item"><div class="details"><strong>Approved visit</strong><p>${pretty(b.date)} · ${b.time}</p></div>${xbutton('Receipt','receipt','secondary small',`data-id="${b.id}"`)}</div>`).join(''):''}</section></div>`;}
function availability(){return `${oldAvailability()}<div class="flex-buttons" style="margin-top:22px">${linkPage('Block time / time off','pBlock','Barber Pro','')}${linkPage('View full calendar','pCalendar','Barber Pro')}</div>`;}
function blockPage(){return `${head('Protect time for yourself.','Block a break or time off in the schedule.')}${errorBox()}<div class="review-grid"><form id="block-time-form" class="panel">${textField('Reason','reason','Lunch break','text','required maxlength="80"')}${textField('Date','date',today,'date',`required min="${today}"`)}${textField('Starts','start','12:00','time','required')}${textField('Ends','end','13:00','time','required')}<button class="btn" type="submit">Block this time</button></form><section><h2>Your blocked time</h2>${extras.blocks.length?extras.blocks.map(b=>`<div class="list-item"><div class="details"><strong>${esc(b.reason)}</strong><p>${pretty(b.date)} · ${b.start}–${b.end}</p></div>${xbutton('Remove','remove-block','secondary small',`data-id="${b.id}"`)}</div>`).join(''):''}</section></div>`;}
function proCalendar(owner=false){return `${head(owner?'Every chair in sync.':'Your calendar, in full.',owner?'Master calendar · Shop appointments':'Lara · Full appointment agenda',`<div class="date-nav"><button class="icon-btn" data-action="prev-day" aria-label="Previous day">${icon('back')}</button><strong>${pretty(state.calendarDate)}</strong><button class="icon-btn" data-action="next-day" aria-label="Next day">${icon('chevron')}</button></div>`)}${timeline()}${extras.blocks.filter(b=>b.date===state.calendarDate).map(b=>`<div class="notice">${icon('clock')} ${esc(b.reason)} · ${b.start}–${b.end}</div>`).join('')}<div class="flex-buttons" style="margin-top:20px">${linkPage('Live tickets','pTickets','Barber Pro')}${!owner?linkPage('Block time','pBlock','Barber Pro'):''}</div>`;}
function proProfile(){const b=activeStaff(),v=extras.barberProfiles?.[activeBarberId()]||{};return `<div class="narrow">${head('Put your craft front and center.','Edit Lara’s public profile.')}<form id="barber-profile-form" class="panel"><div class="row">${photo(b,'avatar square')}<div><h2>${esc(v.name||b.name)}</h2></div></div>${textField('Display name','name',v.name||b.name,'text','required maxlength="80"')}${textField('Specialties','specialty',v.specialty||b.specialty,'text','required maxlength="180"')}<label class="field">About you<textarea name="bio" rows="4" maxlength="600">${esc(v.bio||'Precision cuts. Relaxed energy. A chair you’ll come back to.')}</textarea></label><button class="btn" type="submit">Save profile</button></form></div>`;}
function notificationsPage(){const own=state.role==='Customer',items=own?bookings.filter(b=>b.client==='John B.'&&b.ticket?.status==='awaiting_approval').map(b=>({title:'Your final ticket is ready',body:barbers.find(x=>x.id===b.barber).name+' finished your cut. Review services and choose your tip.',page:'cApproval',id:b.id})):bookings.filter(b=>b.ticket?.status==='changes_requested'&&(state.role==='Owner HQ'||b.barber===activeBarberId())).map(b=>({title:'Client requested a correction',body:b.client+': '+b.ticket.note,page:'pTicket',id:b.id}));const defaults=own?[['Upcoming appointment','Find your booking details in My visits.','bookings']]:state.role==='Barber Pro'?[['Your day is ready','Review your appointments and open tickets.','pTickets']]:[['Schedule request','Review a team member’s availability.','hMember'],['Weekly report','Your performance report is ready.','hPerformance']];return `${head('Stay one step ahead.','Updates for '+state.role.toLowerCase()+'.')}<div class="list">${[...items,...defaults.map(([title,body,page])=>({title,body,page}))].map(n=>`<button class="notification-row" data-x="notification" data-page="${n.page}" data-id="${n.id||''}">${icon('bell')}<div><h3>${n.title}</h3><p>${esc(n.body)}</p></div>${icon('chevron')}</button>`).join('')}</div>`;}
function team(){return `${head('Great people make the place.','Your team at McCormick Ranch.',linkPage('Invite a barber','hInvite','Owner HQ',''))}<div class="profile-results">${barbers.map(b=>`<button class="profile-result" data-x="member" data-id="${b.id}">${photo(b,'avatar square')}<div><h2>${b.name}</h2><p>${b.specialty}</p><small>${b.bookings} appointments · ${money(b.ticket)} avg. ticket</small></div><span class="badge">On shift</span>${icon('chevron')}</button>`).join('')}</div>${extras.invitations.length?`<div class="section-head"><h2>invitations</h2></div>${extras.invitations.map(i=>`<div class="list-item"><div class="details"><strong>${esc(i.name)}</strong><p>${esc(i.email)} · ${i.role}</p></div><span class="badge">Preview saved</span></div>`).join('')}`:''}`;}
function memberPage(){const b=barbers.find(x=>x.id===state.member)||barbers[0];return `${head(b.name,'Team member · Barber',linkPage('All team members','team','Owner HQ'))}<div class="review-grid"><section class="panel"><div class="row">${photo(b,'avatar square')}<div><h2>${b.name}</h2></div></div><div class="line-item"><span>Appointments this month</span><strong>${b.bookings}</strong></div><div class="line-item"><span>Average ticket</span><strong>${money(b.ticket)}</strong></div><div class="line-item"><span>Role</span><strong>Barber</strong></div><div class="notice">Role permissions: own schedule, assigned clients, live tickets and earnings. Owner access is not included.</div></section><section><h2>Availability & services</h2><div class="list-item"><div><strong>Monday–Friday</strong></div></div><div class="list-item"><div><strong>Saturday</strong><p>10 AM–4 PM · Sunday closed</p></div></div><div class="flex-buttons" style="margin-top:22px">${linkPage('View shop calendar','calendar','Owner HQ')}${linkPage('Shop services','hServices','Owner HQ')}</div></section></div>`;}
function invitePage(){return `<div class="narrow">${head('Build your best team.','Create an invitation preview. No email will be sent.',linkPage('Back to team','team','Owner HQ'))}<form id="dedicated-invite" class="panel">${textField('Full name','name','','text','required maxlength="80"')}${textField('Email address','email','','email','required')}<label class="field">Team role<select name="role"><option>Barber</option><option>Receptionist</option></select></label><button class="btn full" type="submit" style="margin-top:22px">Save invitation preview</button><p id="invite-result" class="chart-note"></p></form></div>`;}
function payoutPage(owner){const approved=bookings.filter(b=>b.ticket?.approval&&(owner||b.barber===activeBarberId()));const total=approved.reduce((n,b)=>n+b.ticket.approval.totalCents,0);return `${head(owner?'Every transaction, accounted for.':'Your work, clearly accounted for.',owner?'Transactions and payouts · ledger':'Payout detail · Lara')}<div class="review-grid"><section class="panel"><h2>Client-approved tickets</h2><h1 style="margin-top:20px">${cents(total)}</h1><p class="muted">${approved.length} approved ticket${approved.length===1?'':'s'} · Includes optional post-service tips</p></section><section class="panel"><h2>Payout details</h2><div class="line-item"><span>Status</span><strong>Scheduled</strong></div><div class="line-item"><span>Destination</span><strong>Account ending 4242</strong></div><div class="line-item"><span>Weekly payout</span><strong>${owner?'$8,940':'$1,280'}</strong></div></section></div><div class="section-head"><h2>Approved ticket history</h2></div>${approved.length?approved.map(b=>`<div class="list-item"><div class="details"><strong>${esc(b.client)} · ${pretty(b.date)}</strong><p>Services ${cents(b.ticket.approval.subtotalCents)} + tip ${cents(b.ticket.approval.tipCents)} · v${b.ticket.approval.revision}</p></div><strong>${cents(b.ticket.approval.totalCents)}</strong></div>`).join(''):'<div class="empty"><h2>No approved tickets yet.</h2><p>Finalize a live ticket and have the Customer approve it to populate this ledger.</p></div>'}`;}
function performancePage(){return `${head('The team behind the numbers.','Barber performance · Monthly figures')}<div class="table-wrap"><table><thead><tr><th>Barber</th><th>Appointments</th><th>Average ticket</th><th>Rating</th><th>Booked services</th></tr></thead><tbody>${barbers.map(b=>`<tr><td><div class="row">${photo(b)}<strong>${b.name}</strong></div></td><td>${b.bookings}</td><td>${money(b.ticket)}</td><td>${b.rating} / 5</td><td>${money(b.bookings*b.ticket)}</td></tr>`).join('')}</tbody></table></div>${linkPage('Transactions & payouts','hPayouts','Owner HQ','','style="margin-top:22px"')}`;}
function rewards(){const goal=extras.loyalty?.threshold||5,reward=extras.loyalty?.reward||10,left=Math.max(0,goal-extras.punches);return `<div class="reward-page">${head('Good looks. Great rewards.','A punch follows a completed, client-approved visit.')}<div class="reward"><div class="reward-head"><span class="logo">HAIRFLIX</span>${icon('crown')}</div><div class="punches">${Array.from({length:goal},(_,i)=>`<span class="punch ${i<extras.punches?'filled':''}">${i<extras.punches?icon('scissors'):''}</span>`).join('')}</div><h2>${left?left+' more visit'+(left===1?'':'s')+' to $'+reward+' off.':'Your reward is unlocked.'}</h2></div><div class="notice">Each approved completed ticket earns one punch, once. No punch for booking, rescheduling, cancellations or simply checking in. Reward redemption is a preview; no discount is automatically added to a live ticket.</div>${linkPage('View offers','cOffers','Customer','','style="margin-top:22px"')}</div>`;}
function loyaltyPage(){const p=extras.loyalty||{threshold:5,reward:10};return `${head('Give regulars a reason to return.','Loyalty program management · settings')}<div class="review-grid"><form id="loyalty-form" class="panel"><h2>Punch-card program</h2>${textField('Completed visits required','threshold',p.threshold,'number','required min="3" max="8" step="1"')}${textField('Reward value ($)','reward',p.reward,'number','required min="1" max="100" step="1"')}<p class="chart-note">One punch is earned only after a final ticket is client-approved. Duplicate approvals do not earn duplicate punches.</p><button class="btn" type="submit" style="margin-top:18px">Save program</button></form><section class="panel"><h2>Member activity</h2><div class="line-item"><span>John B.</span><strong>${extras.punches} punches</strong></div><div class="line-item"><span>Approved visits</span><strong>${bookings.filter(b=>b.rewardCredited).length}</strong></div>${linkPage('Preview customer card','rewards','Customer','secondary','style="margin-top:18px"')}</section></div>`;}
function marketingPage(){return `${head('Bring them back for a great cut.','Build a campaign preview. Nothing is sent to customers.')}<div class="review-grid"><form id="campaign-form" class="panel"><h2>Create a promotion</h2>${textField('Campaign name','title','A fresh start','text','required maxlength="80"')}<label class="field">Audience<select name="audience"><option>Returning clients</option><option>New clients</option><option>All clients</option></select></label><label class="field">Message<textarea name="body" rows="4" maxlength="500" required>Ready for a fresh cut? Find a time with your favorite barber.</textarea></label><button class="btn" type="submit">Save campaign draft</button></form><section><h2>Your campaign drafts</h2>${extras.campaigns.map(c=>`<div class="panel" style="margin-top:16px"><h3>${esc(c.title)}</h3><small>${esc(c.audience)} · Draft only</small><p style="margin-top:12px">${esc(c.body)}</p></div>`).join('')||'<div class="notice">No drafts yet. Create one to preview the promotion here.</div>'}</section></div>`;}
function shopMessages(){return `${head('Keep the conversation going.','Owner communications center · inbox')}<div class="inbox-layout"><section class="inbox-threads">${['John B.','Lara','Jose'].map((n,i)=>`<button data-x="thread" data-index="${i}" class="${(state.thread||0)===i?'selected':''}"><strong>${n}</strong><p>${i===0?'Question about my next visit':i===1?'Schedule update':'Thanks for the help'}</p></button>`).join('')}</section><section class="panel"><h2>${['John B.','Lara','Jose'][state.thread||0]}</h2><div class="message-bubble">${state.thread===1?'Could we review my hours for Friday?':state.thread===2?'Thanks for helping with the schedule.':'Can I add a beard sculpt when I come in?'}</div>${(extras.shopMessages||[]).filter(m=>m.thread===(state.thread||0)).map(m=>`<div class="message-bubble out">${esc(m.body)}</div>`).join('')}<form id="shop-message-form" class="message-form"><input name="body" aria-label="shop reply" placeholder="Write a reply…" maxlength="500" required><button class="btn" type="submit" aria-label="Save shop reply">${icon('send')}</button></form></section></div>`;}
function editorLines(t){const forms=[...document.querySelectorAll('.ticket-line-form')];return forms.map(f=>{if(!f.reportValidity())throw new Error('Check the service name, price and quantity.');const d=new FormData(f),old=t.lines.find(l=>l.id===f.dataset.line);return {...old,name:String(d.get('name')).trim(),cents:Math.round(Number(d.get('price'))*100),qty:1};});}
function saveEditor(){const b=freshVisit(state.visitId),t=b?.ticket;if(!t)throw new Error('Open a live ticket first.');if(state.role==='Customer'||(state.role==='Barber Pro'&&b.barber!==activeBarberId()))throw new Error('This ticket belongs to another barber. Choose one of your own tickets.');const rev=Number(document.querySelector('#ticket-line-editor')?.dataset.revision);if(rev!==t.revision)throw new Error('This ticket changed in another tab. Reopen it and review the latest version.');const lines=editorLines(t);if(JSON.stringify(lines)!==JSON.stringify(t.lines))HFTickets.edit(t,lines);save();return b;}
function withTicket(action){if(state.role==='Customer')throw new Error('Switch to Barber Pro to change a live ticket.');const b=freshVisit(state.visitId);if(!b?.ticket)throw new Error('Choose a ticket first.');if(state.role==='Barber Pro'&&b.barber!==activeBarberId())throw new Error('This ticket belongs to another barber.');action(b.ticket,b);save();return b;}
function openApproval(id){state.visitId=id;state.postTip=null;state.tipCustom='';state.pageError='';state.role='Customer';go('cApproval');}
function commitCatalog(){extras.catalog=services.map(s=>({...s}));save();}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;const d=el.dataset;if(d.action==='reset-confirm'){extras.saved=['alex'];extras.punches=3;extras.reviews=[];extras.blocks=[];extras.invitations=[];extras.campaigns=[];extras.shopMessages=[];extras.seeded=true;state.visitId=null;save();render();return;}if(!d.x)return;state.pageError='';try{switch(d.x){
 case'map':go('map');break;
 case'goto':if(d.r)state.role=d.r;if(d.page==='book')startBooking();else if(d.page==='success'){state.latest=bookings.find(b=>b.client==='John B.')?.id;go('success');}else go(d.page);break;
 case'try-ticket':{const b=seedVisit();state.role='Barber Pro';state.visitId=b.id;save();go('pTicket');break;}
 case'open-visit':state.visitId=d.id;go('pAppointment');break;
 case'start-ticket':openTicketFor(d.id);go('pTicket');break;
 case'save-lines':saveEditor();render();toast('Live ticket updated.');break;
 case'remove-line':{const b=saveEditor();HFTickets.edit(b.ticket,b.ticket.lines.filter(l=>l.id!==d.line));save();render();break;}
 case'review-ticket':saveEditor();go('pFinalize');break;
 case'finalize-ticket':withTicket(t=>HFTickets.finalize(t));render();toast('Ticket finalized. Send it when you’re ready.');break;
 case'send-ticket':withTicket((t,b)=>{HFTickets.send(t);b.status='awaiting_approval';});go('pTicket');toast('request ready in Customer → Checkout.');break;
 case'reopen-ticket':withTicket((t,b)=>{HFTickets.reopen(t);b.status='in_service';});state.postTip=null;go('pTicket');toast('Previous approval request withdrawn.');break;
 case'preview-client':{const b=visitFor();if(b.client!=='John B.')throw new Error('Customer preview is John B. Use the sample live visit to test both roles.');openApproval(b.id);break;}
 case'select-approval':openApproval(d.id);break;
 case'post-tip':state.postTip=d.value==='none'||d.value==='custom'?d.value:Number(d.value);render();break;
 case'approve-ticket':{if(state.role!=='Customer')throw new Error('The client must approve this ticket.');if(!document.querySelector('#approve-services')?.checked)throw new Error('Confirm that you’ve reviewed the final services and prices.');const b=freshVisit(state.visitId);if(!b||b.client!=='John B.')throw new Error('This ticket is not assigned to the current client.');const tip=postTipCents(b.ticket.snapshot?.subtotalCents||0);if(tip===null)throw new Error('Choose no tip or a tip amount first.');HFTickets.approve(b.ticket,Number(d.revision),tip);b.status='completed';b.total=b.ticket.approval.totalCents/100;b.tip=b.ticket.approval.tipCents/100;if(!b.rewardCredited){extras.punches++;b.rewardCredited=true;}save();go('cReceipt');toast('Final services and tip approved. ');break;}
 case'receipt':state.visitId=d.id;state.role='Customer';go('cReceipt');break;
 case'barber-profile':state.barber=d.id;go('cBarberProfile');break;
 case'book-service':state.service=d.id;state.services=[d.id];state.step=0;state.editing=null;state.time='';go('book');break;
 case'book-barber':state.step=1;state.editing=null;state.time='';go('book');break;
 case'save-barber':extras.saved=extras.saved.includes(state.barber)?extras.saved.filter(id=>id!==state.barber):[...extras.saved,state.barber];save();render();break;
 case'filter':state.filter=d.value;render();break;
 case'payment-pref':extras.payment=d.value;save();render();toast('payment preference saved.');break;
 case'offer-details':document.querySelector('#offer-details').innerHTML='<div class="notice">Birthday offer preview: a shop-selected benefit during your birthday month. Eligibility and value will be set by the shop. No automatic discount is applied.</div>';break;
 case'client-detail':state.clientIndex=Number(d.index);go(d.owner==='true'?'hCustomer':'pClient');break;
 case'member':state.member=d.id;go('hMember');break;
 case'notification':if(d.id)state.visitId=d.id;if(d.page==='cApproval'){openApproval(d.id);break;}go(d.page);break;
 case'new-service':state.editService='new';render();document.querySelector('#catalog-service-form input').focus();break;
 case'edit-service':state.editService=d.id;render();document.querySelector('#catalog-service-form input').focus();break;
 case'toggle-service':{const s=services.find(s=>s.id===d.id);if(s.active!==false&&services.filter(x=>x.active!==false).length===1)throw new Error('Keep at least one service enabled.');s.active=s.active===false;commitCatalog();render();break;}
 case'remove-block':extras.blocks=extras.blocks.filter(b=>b.id!==d.id);save();render();break;
 case'thread':state.thread=Number(d.index);render();break;
}}catch(error){state.pageError=error.message;render();toast(error.message);}});
document.addEventListener('change',e=>{if(e.target.id==='ticket-service-select'){const svc=services.find(s=>s.id===e.target.value);document.querySelector('#ticket-add-price').value=svc?svc.price.toFixed(2):'';}});
document.addEventListener('submit',e=>{const form=e.target,d=new FormData(form);if(!['add-ticket-service','request-ticket-change','custom-tip-form','demo-signin','barber-search','customer-profile-form','client-review','client-note-form','catalog-service-form','block-time-form','barber-profile-form','dedicated-invite','loyalty-form','campaign-form','shop-message-form'].includes(form.id))return;e.preventDefault();state.pageError='';try{switch(form.id){
 case'add-ticket-service':{const b=saveEditor(),t=b.ticket,svc=services.find(s=>s.id===d.get('service'));const name=svc?svc.name:String(d.get('customName')).trim();if(!name)throw new Error('Enter a name for the custom service.');const line={id:'line-'+Date.now(),service:svc?.id||'custom',name,cents:Math.round(Number(d.get('price'))*100),qty:1};HFTickets.edit(t,[...t.lines,line]);save();render();toast('Service added to the live ticket.');break;}
 case'request-ticket-change':{const b=freshVisit(state.visitId);if(state.role!=='Customer'||b?.client!=='John B.')throw new Error('Choose your own final ticket first.');HFTickets.requestChanges(b.ticket,d.get('note'));save();state.postTip=null;render();toast('Correction request saved for your barber.');break;}
 case'custom-tip-form':state.tipCustom=String(d.get('tip'));if(postTipCents(0)===null)throw new Error('Enter a valid tip amount between $0 and $1,000.');render();break;
 case'demo-signin':extras.profile.name=String(d.get('name')).trim();state.role=String(d.get('role'));save();go('home');toast('Entered the '+state.role+' demo.');break;
 case'barber-search':state.search=String(d.get('query')).trim();render();break;
 case'customer-profile-form':extras.profile={name:String(d.get('name')).trim(),email:String(d.get('email')).trim(),phone:String(d.get('phone')||'').trim(),preferences:String(d.get('preferences')).trim(),reminders:d.has('reminders')};extras.notificationPrefs={...extras.notificationPrefs,reminders:d.has('reminders')};save();toast('Profile saved on this browser.');break;
 case'client-review':{const b=bookings.find(b=>b.id===d.get('visit')&&b.client==='John B.'&&b.ticket?.status==='approved');if(!b)throw new Error('Choose a completed visit.');const stars=Number(d.get('stars')),body=String(d.get('review')).trim();if(!Number.isInteger(stars)||stars<1||stars>5||body.length<3)throw new Error('Choose a rating and add your feedback.');const review={visit:b.id,barber:b.barber,location:b.location||'scottsdale',review:body,stars,at:Date.now()};extras.reviews=[...extras.reviews.filter(r=>r.visit!==b.id),review];state.feedbackVisit=b.id;save();go('cFeedbackThanks');break;}
 case'client-note-form':extras.clientNotes=extras.clientNotes||{};extras.clientNotes[clientRecords[state.clientIndex].name]=String(d.get('note')).trim();save();toast('client note saved.');break;
 case'catalog-service-form':{const price=Number(d.get('price')),min=Number(d.get('min'));if(!Number.isFinite(price)||price<0||price>1000||!Number.isInteger(min)||min<5||min>240)throw new Error('Check the service price and duration.');const value={id:form.dataset.id==='new'?'svc-'+Date.now():form.dataset.id,name:String(d.get('name')).trim(),desc:String(d.get('desc')).trim(),price,min,active:true};const old=services.findIndex(s=>s.id===value.id);if(old<0)services.push(value);else services[old]=value;state.editService=null;commitCatalog();render();toast('Service menu saved for new bookings. Existing tickets unchanged.');break;}
 case'block-time-form':{const date=String(d.get('date')),start=String(d.get('start')),end=String(d.get('end')),startM=clockMinutes(start),endM=clockMinutes(end);if(endM<=startM)throw new Error('End time must be later than the start time.');if(bookings.some(b=>b.barber===activeBarberId()&&b.date===date&&!['completed','cancelled'].includes(b.status)&&minutes(b.time)<endM&&minutes(b.time)+bookingDuration(b)>startM))throw new Error('This block overlaps an existing appointment. Choose another time.');extras.blocks.push({id:'block-'+Date.now(),barber:'alex',date,start,end,reason:String(d.get('reason')).trim()});save();render();toast('Time blocked in the schedule.');break;}
 case'barber-profile-form':extras.barberProfiles=extras.barberProfiles||{};extras.barberProfiles[activeBarberId()]={name:String(d.get('name')).trim(),specialty:String(d.get('specialty')).trim(),bio:String(d.get('bio')).trim()};Object.assign(activeStaff(),extras.barberProfiles[activeBarberId()]);activeStaff().short=activeStaff().name.split(' ')[0];save();toast('public profile saved.');break;
 case'dedicated-invite':{const v={name:String(d.get('name')).trim(),email:String(d.get('email')).trim(),role:String(d.get('role'))};extras.invitations.push(v);save();document.querySelector('#invite-result').textContent='Invitation preview saved for '+v.name+'. ';break;}
 case'loyalty-form':{const threshold=Number(d.get('threshold')),reward=Number(d.get('reward'));if(!Number.isInteger(threshold)||threshold<3||threshold>8||!Number.isInteger(reward)||reward<1||reward>100)throw new Error('Choose 3–8 visits and a $1–$100 reward.');extras.loyalty={threshold,reward};save();render();toast('loyalty program updated.');break;}
 case'campaign-form':extras.campaigns.push({title:String(d.get('title')).trim(),audience:String(d.get('audience')),body:String(d.get('body')).trim()});save();render();toast('Campaign draft saved. ');break;
 case'shop-message-form':extras.shopMessages=extras.shopMessages||[];extras.shopMessages.push({thread:state.thread||0,body:String(d.get('body')).trim()});save();render();toast('reply saved. ');break;
}}catch(error){state.pageError=error.message;render();toast(error.message);}});
function clockMinutes(s){const [h,m]=s.split(':').map(Number);return h*60+m;}
function rewardCard(){const threshold=extras.loyalty?.threshold||5,reward=extras.loyalty?.reward||10,left=Math.max(0,threshold-extras.punches);return `<div class="reward"><div class="reward-head"><span class="logo">HAIRFLIX</span>${icon('crown')}</div><span class="reward-label">THE GOOD LOOKS CLUB</span><div class="punches" style="flex-wrap:wrap">${Array.from({length:threshold},(_,i)=>`<span class="punch ${i<extras.punches?'filled':''}">${i<extras.punches?icon('scissors'):''}</span>`).join('')}</div><h3>${left?left+' more cut'+(left===1?'':'s')+'. $'+reward+' on us.':'Your $'+reward+' reward is unlocked.'}</h3><p>One punch per client-approved completed visit.</p><button class="text-btn" data-view="rewards">View my punch card ${icon('arrow')}</button></div>`;}
// Shared workspace synchronization is handled by operations.js, including message drafts.
